// РОЗВІДКА: вхід у веб-клієнт 1С + діагностика. ЖОДНИХ ЗАПИСІВ.
const { chromium } = require('playwright');
const fs = require('fs');
(async () => {
  const env = {};
  for (const l of fs.readFileSync('/root/unitex-finrep/secure/odata_write.env','utf8').split('\n')) {
    const m = l.match(/^\s*([A-Z_]+)\s*=\s*(.+?)\s*$/); if (m) env[m[1]] = m[2];
  }
  console.log('КОРИСТУВАЧ:', env.ODATA_USER);
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const ctx = await browser.newContext({ ignoreHTTPSErrors: true, viewport:{width:1400,height:900}, locale:'uk-UA' });
  const page = await ctx.newPage();
  const errs = [], fails = [];
  page.on('console', m => { if (m.type()==='error') errs.push(m.text().slice(0,160)); });
  page.on('pageerror', e => errs.push('PAGEERR ' + String(e).slice(0,160)));
  page.on('requestfailed', r => fails.push(r.url().slice(-70) + ' :: ' + (r.failure()&&r.failure().errorText)));
  page.on('response', r => { if (r.status()>=400) fails.push(r.status()+' '+r.url().slice(-70)); });
  page.on('dialog', d => d.accept());
  await page.goto('https://unitex.rdport.net:29231/DB/', { waitUntil:'load', timeout:60000 });
  await page.waitForTimeout(8000);
  console.log('URL1:', page.url(), '| TITLE1:', await page.title());
  const u = await page.$('#userName'), p = await page.$('#userPassword');
  console.log('поля входу:', !!u, !!p);
  if (u && p) {
    await u.fill(env.ODATA_USER); await p.fill(env.ODATA_PASS);
    await Promise.all([ p.press('Enter'), page.waitForTimeout(25000) ]);
    console.log('URL2:', page.url(), '| TITLE2:', await page.title());
    const t = await page.evaluate(() => document.body ? document.body.innerText : '(немає body)');
    console.log('ТЕКСТ СТОРІНКИ:', t.replace(/\s+/g,' ').slice(0,900) || '(порожньо)');
    const html = await page.content();
    console.log('HTML довжина:', html.length);
    console.log('HTML початок:', html.replace(/\s+/g,' ').slice(0,400));
    await page.screenshot({ path:'/root/webbot/shots/20-after.png', fullPage:false });
  }
  console.log('ПОМИЛКИ JS:', errs.length ? errs.slice(0,8).join(' || ') : 'немає');
  console.log('ЗБІЙНІ ЗАПИТИ:', fails.length ? fails.slice(0,10).join(' || ') : 'немає');
  await browser.close();
})().catch(e => { console.log('ПОМИЛКА:', String(e).slice(0,300)); process.exit(1); });
EOJS
cd /root/webbot && timeout 200 node diag_login.js 2>&1 | tail -30
